        .child {
            display: flex;
            flex-flow: row wrap;
            justify-content: center;
            max-width: 800px;
            margin: 0 auto;
            padding: 20px;
        }
        .child div {
            flex: 0 0 calc(33.33% - 20px);
            margin: 10px;
            text-align: center;
        }

        .child1, .child2, .child3, .child4, .child5, .child6, .child7{
            border: 5px solid #ccc; 
            border-radius: 15px;
            padding: 10px;
            margin: 10px; 
            text-align: center;
            background-color: #f3f3f3; 
            transition: transform 0.3s ease;
        }
        .child1:hover, .child2:hover, .child3:hover, .child4:hover, .child5:hover, .child6:hover, .child7:hover {
            background-color: #41b085;
            transform: scale(1.1);
        }
        img {
            max-width: 100%; 
            height: auto; 
        }
        h3 {
            margin-top: 10px;
        }
        a {
            color: #333333 !important; 
            text-decoration: none;
        }

        @media (max-width: 768px) {
            .child div {
                flex: 0 0 calc(50% - 20px); /* Two columns on medium screens */
            }
        }
        @media (max-width: 480px) {
            .child div {
                flex: 0 0 calc(100% - 20px); /* Single column on small screens */
            }
        }



